WITH history AS (SELECT DATE_TRUNC(`event_date`, DAY) AS period, EXTRACT(DAYOFWEEK FROM `event_date`) AS dow, COUNT(*) AS cnt FROM `fake_project.dataset.orders` WHERE `event_date` >= DATE('2026-05-01') - INTERVAL 28 DAY AND `event_date` < DATE('2026-05-01') GROUP BY period, dow), medians AS (SELECT dow, PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY cnt) AS median FROM history GROUP BY dow), mads AS (SELECT history.dow AS dow, PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY ABS(history.cnt - medians.median)) AS mad FROM history JOIN medians ON history.dow = medians.dow GROUP BY history.dow), counts AS (SELECT dow, COUNT(*) AS n FROM history GROUP BY dow) SELECT medians.dow AS dow, medians.median AS median, mads.mad AS mad, counts.n AS n FROM medians JOIN mads ON medians.dow = mads.dow JOIN counts ON medians.dow = counts.dow